import { useStore } from 'vuex'
import { ref, computed } from 'vue'
import axios from 'axios'
import { API_CONFIG } from '@/config/config'
import { ElMessage } from 'element-plus'

export default function useLike() {
  const store = useStore()
  const moments = ref([]) // 假设传入的moments包含当前页面的动态列表

  const currentUser = computed(() => store.state.user || {})

  const toggleLike = async (resourceType, resourceId) => {
    const urlMap = {
      moment: `${API_CONFIG.BASE_URL}/article/like_moment`,
      comment: `${API_CONFIG.BASE_URL}/article/like_comment`
    }

    // 查找目标资源（从传入的moments中查找）
    let targetResource
    if (resourceType === 'moment') {
      targetResource = moments.value.find(moment => moment.id === resourceId)
    } else if (resourceType === 'comment') {
      for (const moment of moments.value) {
        targetResource = moment.comments.find(comment => comment.id === resourceId)
        if (targetResource) break
      }
    }

    if (!targetResource) {
      console.error(`未找到${resourceType}资源:`, resourceId)
      return null // 或根据需求处理未找到的情况
    }

    // 保存原始状态用于回滚
    const originalIsLiked = targetResource.isLiked
    const originalLikes = targetResource.stats?.likes || 0

    try {
      // 发送点赞请求（去掉is_like参数，由后端自动切换状态）
      const response = await axios.post(urlMap[resourceType], {
        [resourceType === 'moment' ? 'moment_id' : 'comment_id']: resourceId,
        user_id: currentUser.value.id
      }, {
        headers: {
          Authorization: `Bearer ${store.state.token}`
        },
        timeout: 5000
      })

      if (response.data.success) {
        // 获取后端返回的最新状态
        const newIsLiked = response.data.is_liked
        const newLikesCount = response.data.likes_count

        // 更新前端状态
        targetResource.isLiked = newIsLiked
        targetResource.stats = targetResource.stats || { likes: 0 }
        targetResource.stats.likes = newLikesCount

        // 更新like_users列表
        if (newIsLiked) {
          targetResource.like_users = [...(targetResource.like_users || []), currentUser.value.id]
        } else {
          targetResource.like_users = (targetResource.like_users || []).filter(id => id !== currentUser.value.id)
        }

        ElMessage.success(newIsLiked ? '点赞成功' : '已取消点赞')

        return {
          isLiked: newIsLiked,
          likes: newLikesCount
        }
      } else {
        throw new Error(response.data.msg || '操作失败')
      }
    } catch (error) {
      // 回滚状态
      targetResource.isLiked = originalIsLiked
      targetResource.stats.likes = originalLikes
      
      console.error('点赞操作失败:', error)
      ElMessage.error(`操作失败: ${error.response?.data?.msg || '网络错误'}`)
      return null
    }
  }

  return {
    toggleLike,
    moments // 暴露moments以便外部更新（如果需要）
  }
}
